// GERADO por scripts/split-stage-info.mjs — não edite à mão o cabeçalho.
// Fichas de PERSONAGEM (por `id`) das cenas de 2kings. Vem por import() junto com
// o roteiro do livro: quem lê Rute não baixa os nomes de Crônicas.
import type { StageInfo } from "@/lib/rpgStageInfo";

export const CHARS: Record<string, StageInfo> = {
  manasses: { title: "Manassés", subtitle: "Primogênito de José, nascido no Egito (Gn 41:51)", text: "Primeiro filho que José teve no Egito, de Asenate: \"Deus me fez esquecer de todo o meu trabalho, e de toda a casa de meu pai\" — daí Manassés, \"o que faz esquecer\" (Gn 41:51). Jacó o adotou como seu, ao lado de Rúben e Simeão (Gn 48:5); mas, sendo o mais velho, recebeu do avô a mão esquerda, cedendo a bênção maior ao irmão menor (Gn 48:14)." },
  "acabe": {
    title: "Acabe",
    subtitle: "O rei de Israel que fez mais mal do que todos antes dele (1Rs 16:30)",
    text: "\"E fez Acabe, filho de Onri, o que era mau aos olhos do Senhor, mais do que todos os que foram antes dele\" (16:30), e o texto explica por quê: os bezerros de Jeroboão já lhe pareciam pouco, e \"ainda tomou por mulher a Jezabel, filha de Etbaal, rei dos sidônios; e foi e serviu a Baal, e o adorou\" (16:31), levantando altar e casa a Baal em Samaria. Chamou o profeta de \"És tu o perturbador de Israel?\" (18:17) e depois de \"Já me achaste, inimigo meu?\" (21:20). Não era, porém, um homem de uma peça só: viu o fogo cair no Carmelo e a chuva voltar; poupou Ben-Hadade chamando-lhe \"meu irmão\" (20:32) quando Deus o entregara à destruição; deitou-se na cama com o rosto virado por causa de uma horta, e deixou a mulher matar Nabote em seu nome (21:4-16). O julgamento é implacável e exato: \"Porém ninguém fora como Acabe, que se vendera para fazer o que era mau aos olhos do Senhor; porque Jezabel, sua mulher, o incitava\" (21:25). E, mesmo assim, quando ouviu a sentença, \"rasgou as suas vestes, e cobriu a sua carne de saco, e jejuou; e jazia em saco, e andava mansamente\" (21:27) — e Deus, que vê até a humilhação de um homem vendido, adiou o golpe: \"Não viste que Acabe se humilha perante mim?\" (21:29). Morreu disfarçado em Ramote de Gileade, porque disfarce nenhum desvia uma flecha: \"um homem armou o arco, e atirou a esmo, e feriu o rei de Israel por entre as fivelas e as couraças\" (22:34). Ficou de pé no carro até a tarde, e ao lavarem o carro \"os cães lamberam o seu sangue\" (22:38).",
  },
  "jezabel": {
    title: "Jezabel",
    subtitle: "A filha de Etbaal que armou o jejum e as cartas seladas (1Rs 16:31; 21:8)",
    text: "Princesa fenícia, \"Jezabel, filha de Etbaal, rei dos sidônios\" (16:31), trouxe consigo o culto de Baal para dentro do palácio de Samaria e tratou a fé de Israel como um estorvo administrativo: sustentava à sua mesa \"os quatrocentos profetas de Aserá\" (18:19) enquanto ia \"destruindo Jezabel os profetas do Senhor\" (18:4) — foi por causa dela que Obadias escondeu cem deles em duas covas. Depois do Carmelo, não se abalou nem discutiu: mandou recado, com a serenidade de quem marca hora, \"Assim me façam os deuses, e outro tanto, se de certo amanhã a estas horas não puser a tua vida como a de um deles\" (19:2), e pôs em fuga o homem que enfrentara quatrocentos e cinqüenta. O seu retrato definitivo é a vinha: diante do marido de cara virada para a parede, perguntou \"Governas tu agora no reino de Israel?\" (21:7) e resolveu o assunto com papelada. \"Então escreveu cartas em nome de Acabe, e as selou com o seu sinete\" (21:8), e nelas mandou o roteiro completo — \"Apregoai um jejum, e ponde Nabote diante do povo\" (21:9), dois falsos testemunhos, e o apedrejamento. Usou a religião como instrumento do crime: convocou jejum para matar um justo. A palavra do SENHOR sobre ela é uma das mais duras da Bíblia: \"Os cães comerão a Jezabel junto ao antemuro de Jizreel\" (21:23).",
  },
  "elias": {
    title: "Elias, o tisbita",
    subtitle: "O profeta dos corvos, do fogo do Carmelo e da voz mansa e delicada (1Rs 17–19)",
    text: "Entra na história sem genealogia e sem aviso, \"Elias, o tisbita, dos moradores de Gileade\", plantado diante de Acabe: \"Vive o SENHOR Deus de Israel, perante cuja face estou, que nestes anos nem orvalho nem chuva haverá, senão segundo a minha palavra\" (17:1) — atacou Baal exatamente onde Baal dizia reinar, na chuva. Escondido em Querite, foi sustentado pelo que a Lei chamava imundo: \"E os corvos lhe traziam pão e carne pela manhã; como também pão e carne à noite\" (17:6). Em Sarepta, terra da própria Jezabel, viveu do último punhado de farinha de uma viúva e viu o milagre da provisão diária: \"A farinha da panela não se acabará, e o azeite da botija não faltará\" (17:14). No Carmelo pôs Israel diante da única pergunta que importava — \"Até quando coxeareis entre dois pensamentos? Se o Senhor é Deus, segui-o, e se Baal, segui-o\" (18:21) —, encharcou o altar de água e orou uma oração de trinta segundos; \"Então caiu fogo do Senhor, e consumiu o holocausto, e a lenha, e as pedras, e o pó, e ainda lambeu a água que estava no rego\" (18:38), e o povo caiu de rosto: \"Só o Senhor é Deus!\" (18:39). E no dia seguinte, uma ameaça de mulher o pôs a correr: \"foi sentar-se debaixo de um zimbro; e pediu para si a morte\", dizendo \"Já basta, ó Senhor; toma agora a minha vida, pois não sou melhor do que meus pais\" (19:4). Deus não o repreendeu: mandou um anjo com pão e água, deixou-o dormir, e o levou quarenta dias até Horebe. Ali não estava no vento, nem no terremoto, nem no fogo — \"e depois do fogo uma voz mansa e delicada\" (19:12) —, e a pergunta que ouviu duas vezes foi \"Que fazes aqui, Elias?\" (19:13). À queixa \"só eu fiquei\" (19:14), a resposta desfez a solidão do herói: \"Também deixei ficar em Israel sete mil: todos os joelhos que não se dobraram a Baal\" (19:18). Deus lhe deu trabalho, um sucessor e companhia — e é assim que se cura um profeta esgotado.",
  },
  "eliseu": {
    title: "Eliseu",
    subtitle: "O lavrador das doze juntas, chamado pela capa de Elias (1Rs 19:19)",
    text: "Deus o nomeou antes de ele saber: \"a Eliseu, filho de Safate de Abel-Meolá, ungirás profeta em teu lugar\" (19:16) — resposta do céu a um profeta que pedira a morte debaixo de um zimbro. Elias o encontrou no trabalho: \"achou a Eliseu, filho de Safate, que andava lavrando com doze juntas de bois adiante dele, e ele estava com a duodécima\" (19:19), sinal de uma casa próspera, com terra e gado que ele estava para herdar. O chamado veio sem discurso, sem oráculo, sem imposição de mãos: \"e lançou a sua capa sobre ele\". Ele correu atrás e pediu só uma coisa: \"Deixa-me beijar a meu pai e a minha mãe, e então te seguirei\" (19:20). Voltou — e a despedida foi um incêndio: \"tomou a junta de bois, e os matou, e com os aparelhos dos bois cozeu as carnes, e as deu ao povo, e comeram\" (19:21). Queimou o arado para cozinhar os próprios bois e repartiu o banquete com a aldeia: não deixou meio de voltar atrás. \"então se levantou e seguiu a Elias, e o servia\" — e por anos a sua função foi essa, servir, antes de qualquer milagre. Quem põe a mão no arado e olha para trás não é apto (Lc 9:62); Eliseu resolveu o problema queimando o arado.",
  },
  "ben-hadade": {
    title: "Ben-Hadade",
    subtitle: "O rei da Síria dos trinta e dois reis, poupado por Acabe (1Rs 20)",
    text: "Rei de Damasco, aparece primeiro como espada de aluguel: Asa lhe mandou a prata e o ouro do templo, e ele feriu por encomenda as cidades do norte de Israel (15:18-20). Depois sobe como senhor de guerra, com trinta e dois reis vassalos, e cerca Samaria exigindo tudo: \"A tua prata e o teu ouro são meus; e tuas mulheres e os melhores de teus filhos são meus\" (20:3). Gabou-se de que \"o pó de Samaria não bastará para encher as mãos de todo o povo que me segue\" (20:10) e recebeu de volta o provérbio que o desmascarou: \"Não se gabe quem se cinge das armas, como aquele que as descinge\" (20:11). Foi derrotado à hora do meio-dia enquanto \"estava bebendo e embriagando-se nas tendas, ele e os reis, os trinta e dois reis\" (20:16). No ano seguinte voltou com a teologia dos seus conselheiros: \"Seus deuses são deuses dos montes, por isso foram mais fortes do que nós; mas pelejemos com eles em campo raso\" (20:23) — e o SENHOR o desmentiu em pessoa, com o vale escolhido por ele: \"Porquanto os sírios disseram: O Senhor é Deus dos montes, e não Deus dos vales; toda esta grande multidão entregarei nas tuas mãos\" (20:28). Escondendo-se de câmara em câmara em Afeque, salvou-se pela reputação alheia: \"ponhamos, pois, sacos aos lombos, e cordas às cabeças\" (20:31), e a mensagem \"Diz o teu servo Ben-Hadade: Deixa-me viver\" (20:32) fez Acabe abrir os braços — \"Pois ainda vive? É meu irmão\". A clemência mal colocada custou a Acabe a própria vida (20:42).",
  },
  "josafa": {
    title: "Jeosafá",
    subtitle: "O rei de Judá que pediu para consultar a palavra do SENHOR (1Rs 22:5)",
    text: "Filho de Asa, reinou vinte e cinco anos em Jerusalém e \"andou em todos os caminhos de seu pai Asa, não se desviou deles, fazendo o que era reto aos olhos do Senhor\" (22:43); \"era o nome de sua mãe Azuba, filha de Sili\" (22:42). Fez a paz com o reino do norte depois de gerações de guerra — \"E Jeosafá esteve em paz com o rei de Israel\" (22:45) —, e essa paz foi ao mesmo tempo a sua virtude e a sua armadilha. Aliou-se a Acabe com uma entrega quase excessiva: \"Serei como tu, e o meu povo como o teu povo, e os meus cavalos como os teus cavalos\" (22:4). Mas, no meio do entusiasmo militar, foi ele — não o rei de Israel — quem se lembrou de Deus: \"Peço-te, consulta hoje a palavra do Senhor\" (22:5); e, ouvindo os quatrocentos aplaudirem em coro, insistiu com a pergunta que salva reinos: \"Não há aqui ainda algum profeta do Senhor, ao qual possamos consultar?\" (22:7). Ao ouvir Acabe reclamar de Micaías, repreendeu-o com delicadeza: \"Não fale o rei assim\" (22:8). Ainda assim subiu à batalha, vestido de rei enquanto o aliado se disfarçava, e quase morreu por isso: \"porém Jeosafá gritou\" (22:32), e os capitães o largaram. \"Todavia os altos não se tiraram\" (22:44), e os seus navios de Társis se quebraram em Eziom-Geber (22:49). Um rei bom, que perguntava certo e escolhia mal as companhias.",
  },
  "acazias": {
    title: "Acazias",
    subtitle: "O filho de Acabe que serviu a Baal (1Rs 22:52-54)",
    text: "\"Assim dormiu Acabe com seus pais; e Acazias, seu filho, reinou em seu lugar\" (22:40). Reinou pouco: \"E Acazias, filho de Acabe, começou a reinar sobre Israel, em Samaria, no ano dezessete de Jeosafá, rei de Judá; e reinou dois anos sobre Israel\" (22:52). O veredicto sobre ele soma três heranças, e a do meio é a que mais pesa: \"E fez o que era mau aos olhos do Senhor; porque andou no caminho de seu pai, como também no caminho de sua mãe, e no caminho de Jeroboão, filho de Nebate, que fez pecar a Israel\" (22:53). Poucos reis recebem essa menção explícita à mãe — mas era Jezabel, e a casa que ela montou continuou de pé depois de morto o marido. O último traço é a religião escolhida sem disfarce: \"E serviu a Baal, e adorou-o, e provocou a ira do Senhor Deus de Israel, conforme a tudo quanto fizera seu pai\" (22:54). Ainda tentou sociedade marítima com Judá, e foi recusado: \"Vão os meus servos com os teus servos nos navios. Porém Jeosafá não quis\" (22:50). O fogo do Carmelo caíra diante dos olhos da geração dele; não bastou. A fé não se herda por sangue, e o filho de Acabe é a prova.",
  },
  "abi-filha-de-zacarias": { title: "Abi, filha de Zacarias", subtitle: "A mãe de Ezequias, rei de Judá (2Rs 18:2)", text: "A Escritura a nomeia numa linha só: \"era o nome de sua mãe Abi, filha de Zacarias\" (2Rs 18:2). O marido dela foi Acaz, que \"até a seu filho fez passar pelo fogo, segundo as abominações dos gentios\" (2Rs 16:3); o filho foi o rei de quem se escreveu: \"No Senhor Deus de Israel confiou, de maneira que depois dele não houve quem lhe fosse semelhante entre todos os reis de Judá\" (2Rs 18:5). Da mesma casa saiu o pai que queimou um filho e o filho que \"fez em pedaços a serpente de metal que Moisés fizera\" (2Rs 18:4). A graça não se herda por sangue, mas Deus a faz nascer dentro de casas arruinadas." },
  "acaz-de-juda": { title: "Acaz", subtitle: "Rei de Judá, filho de Jotão (2Rs 16:1)", text: "Dele se diz o contrário do que se diz de Davi: \"não fez o que era reto aos olhos do Senhor seu Deus, como Davi, seu pai\" (2Rs 16:2), e foi além de todos, porque \"até a seu filho fez passar pelo fogo, segundo as abominações dos gentios\" (2Rs 16:3). Cercado por Rezim e por Peca, não buscou o SENHOR, mas a Assíria: \"Eu sou teu servo e teu filho; sobe, e livra-me\" (2Rs 16:7), e pagou com a prata da casa do SENHOR. De Damasco mandou ao sacerdote Urias \"o desenho e o modelo do altar\" pagão, e o altar de bronze foi empurrado para o lado (2Rs 16:10-14). A este rei Isaías ofereceu um sinal, e ele recusou — \"Não pedirei, nem tentarei ao Senhor\" (Is 7:12) —, e ouviu mesmo assim a promessa maior: \"Eis que a virgem conceberá, e dará à luz um filho\" (Is 7:14)." },
  "acazias-de-juda": { title: "Acazias", subtitle: "Rei de Judá, filho de Jeorão e de Atalia (2Rs 8:25-26)", text: "Reinou um ano só, e \"era o nome de sua mãe Atalia, filha de Onri, rei de Israel\" (2Rs 8:26) — a casa de Acabe já entrara em Judá pelo casamento. \"E andou no caminho da casa de Acabe, e fez o que era mal aos olhos do Senhor, como a casa de Acabe, porque era genro da casa de Acabe\" (2Rs 8:27). Descera a Jizreel apenas \"para ver a Jorão\" (2Rs 8:29) e foi apanhado pelo juízo que varria o Norte: Jeú ordenou \"Feri também a este\", e ele \"fugiu a Megido, e morreu ali\" (2Rs 9:27). A aliança com a casa ímpia custou-lhe a vida e deixou o trono de Davi nas mãos da própria mãe." },
  "acbor-filho-de-micaias": { title: "Acbor, filho de Micaías", subtitle: "Um dos cinco que Josias enviou a consultar o SENHOR (2Rs 22:12)", text: "Quando o rei ouviu as palavras do livro achado e rasgou as vestes, mandou chamar cinco homens — \"a Hilquias, o sacerdote, a Aicão, filho de Safã, a Acbor, filho de Micaías, a Safã o escrivão e a Asaías, o servo do rei\" (2Rs 22:12). A ordem foi uma só: \"Ide, e consultai o Senhor por mim, pelo povo e por todo o Judá\" (2Rs 22:13). Acbor subiu com eles \"à profetisa Hulda\" (2Rs 22:14) e voltou trazendo ao trono a sentença e a misericórdia. A Escritura o guarda não por façanha, mas por ter estado entre os que levaram a sério a Palavra encontrada." },
  "adrameleque": { title: "Adrameleque", subtitle: "Filho de Senaqueribe, um dos que o mataram em Nínive (2Rs 19:37)", text: "O rei que zombara do Deus vivo voltou derrotado para casa, e a espada o achou dentro do templo do seu próprio deus: \"estando ele prostrado na casa de Nisroque, seu deus, Adrameleque e Sarezer, seus filhos, o feriram à espada\" (2Rs 19:37). Cumpriu-se à letra o que Isaías dissera: \"à espada o farei cair na sua terra\" (2Rs 19:7). Os assassinos \"escaparam para a terra de Ararate\", e Esar-Hadom reinou em lugar do pai. É pungente que Adrameleque seja também o nome de um ídolo a quem \"os sefarvitas queimavam seus filhos no fogo\" (2Rs 17:31): o culto que devora filhos devolveu ao rei da Assíria filhos que o mataram." },
  "aicao-filho-de-safa": { title: "Aicão, filho de Safã", subtitle: "Oficial de Josias, pai do governador Gedalias (2Rs 22:12; 25:22)", text: "Filho do escrivão Safã, foi um dos cinco enviados por Josias com a ordem \"Ide, e consultai o Senhor por mim, pelo povo e por todo o Judá\" (2Rs 22:13), e esteve diante de Hulda quando ela anunciou o mal e o adiamento. A sua casa atravessou o desastre: anos depois, o rei da Babilônia \"pôs sobre ele, por governador a Gedalias, filho de Aicão, filho de Safã\" (2Rs 25:22). E foi a mão desse mesmo Aicão que salvou um profeta da morte: \"Porém a mão de Aicão, filho de Safã, foi com Jeremias, para que o não entregassem na mão do povo, para ser morto\" (Jr 26:24). Três gerações de escribas fiéis, num reino que se despedaçava." },
  "amazias-de-juda": { title: "Amazias", subtitle: "Rei de Judá, filho de Joás (2Rs 14:1)", text: "\"E fez o que era reto aos olhos do Senhor, ainda que não como seu pai Davi\" (2Rs 14:3). Vingou o pai assassinado, mas guardou a lei: \"os filhos dos assassinos não matou\", porque estava escrito \"Não matarão os pais por causa dos filhos\" (2Rs 14:6). Depois \"feriu a dez mil edomitas no vale do Sal\" (2Rs 14:7) e o coração se lhe ensoberbeceu; desafiou Israel — \"Vem, vejamo-nos face a face\" (2Rs 14:8) — e ouviu a parábola do cardo e do cedro com o aviso: \"gloria-te disso, e fica em tua casa\" (2Rs 14:10). Não ouviu, foi ferido em Bete-Semes, viu o muro de Jerusalém rompido, e acabou como o pai: \"conspiraram contra ele em Jerusalém, e fugiu para Laquis\" (2Rs 14:19)." },
  "amom": { title: "Amom", subtitle: "Rei de Judá, filho de Manassés (2Rs 21:19)", text: "Reinou dois anos, e \"era o nome de sua mãe Mesulemete, filha de Harus, de Jotbá\" (2Rs 21:19). Herdou de Manassés os ídolos sem herdar-lhe o arrependimento: \"serviu os ídolos, a que seu pai tinha servido, e se inclinou diante deles\" (2Rs 21:21), e assim \"deixou ao Senhor Deus de seus pais\" (2Rs 21:22). Morreu dentro da própria casa: \"os servos de Amom conspiraram contra ele, e mataram o rei em sua casa\" (2Rs 21:23). O povo da terra vingou-o e pôs no trono o filho de oito anos; e o nome de Amom ficou na genealogia do Cristo — \"Manassés gerou a Amom; e Amom gerou a Josias\" (Mt 1:10)." },
  "anjo-do-senhor": { title: "O anjo do SENHOR", subtitle: "O mensageiro por quem o SENHOR fala e fere em 2 Reis (2Rs 1:3; 19:35)", text: "Não é Deus desenhado como figura, mas o mediador visível por quem a sua palavra chega: \"Mas o anjo do Senhor disse a Elias, o tisbita: Levanta-te, sobe para te encontrares com os mensageiros do rei de Samaria\" (2Rs 1:3). Ao terceiro capitão, que se pôs de joelhos e suplicou, é ele quem autoriza a descida: \"Desce com este, não temas\" (2Rs 1:15) — a mesma presença que consumira dois cinqüenta poupa o que suplica. E, na noite em que Jerusalém não tinha exército, \"saiu o anjo do Senhor, e feriu no arraial dos assírios a cento e oitenta e cinco mil deles\" (2Rs 19:35). Onde a Assíria contava carros, o SENHOR não precisou de nenhum." },
  "argobe": { title: "Argobe", subtitle: "Morto no paço de Samaria com o rei Pecaías (2Rs 15:25)", text: "Um nome no meio de um golpe de estado. Peca, capitão do rei, \"conspirou contra ele, e o feriu em Samaria, no paço da casa do rei, juntamente com Argobe e com Arié, e com ele cinqüenta homens dos filhos dos gileaditas\" (2Rs 15:25). A Escritura não diz se Argobe morreu ao lado do rei ou ao lado do conspirador: só o registra na sala onde correu o sangue. Assim ia o reino do Norte nos seus últimos anos — Zacarias reinou \"seis meses\" (2Rs 15:8), Salum \"um mês inteiro em Samaria\" (2Rs 15:13), e o palácio virou o lugar mais perigoso da terra." },
  "arie": { title: "Arié", subtitle: "Morto no paço de Samaria com o rei Pecaías (2Rs 15:25)", text: "A Escritura o nomeia uma vez só, na hora do assassinato de Pecaías: Peca o feriu \"no paço da casa do rei, juntamente com Argobe e com Arié\" (2Rs 15:25). Um homem cuja história inteira cabe numa oração subordinada. Em Israel, naqueles anos, os reinados já se contavam em meses e as mortes em conspirações: Zacarias, Salum, Pecaías e Peca caíram, cada um pela mão do seguinte. Deus dissera a Jeú que os seus filhos reinariam \"até à quarta geração\" (2Rs 15:12) — passado o prazo, não sobrou casa nenhuma de pé em Samaria." },
  "asaias-servo-do-rei": { title: "Asaías", subtitle: "O servo do rei, enviado por Josias a Hulda (2Rs 22:12)", text: "Josias o nomeia entre os cinco que devem \"consultai o Senhor por mim, pelo povo e por todo o Judá\" (2Rs 22:13): \"a Safã o escrivão e a Asaías, o servo do rei\" (2Rs 22:12). Não é sacerdote nem escriba — é o homem da casa do rei, e por isso mesmo o portador da resposta ao trono. Com Hilquias, Aicão, Acbor e Safã foi \"à profetisa Hulda\" (2Rs 22:14) e ouviu que o mal viria, mas não nos dias daquele rei que se humilhara. \"Então tornaram a trazer ao rei a resposta\" (2Rs 22:20) — e daquele recado nasceu a maior reforma de Judá." },
  "atalia": { title: "Atalia", subtitle: "Filha de Onri, mãe de Acazias, usurpadora do trono de Davi (2Rs 11:1)", text: "Com a casa de Acabe no sangue e o filho morto por Jeú, fez o que nenhum inimigo de Judá conseguira: \"levantou-se, e destruiu toda a descendência real\" (2Rs 11:1) — a lâmpada prometida a Davi quase se apagou por dentro. Reinou seis anos sobre o país enquanto um menino crescia escondido na casa do SENHOR (2Rs 11:3). No dia da coroação ouviu as trombetas, correu ao templo e só teve tempo de gritar: \"Traição! Traição!\" (2Rs 11:14). Joiada não a deixou morrer no santuário — \"Não a matem na casa do Senhor\" (2Rs 11:15) —, e ela caiu junto à casa do rei, pelo caminho da entrada dos cavalos." },
  "azarias-uzias": { title: "Azarias (Uzias)", subtitle: "Rei de Judá, leproso até o dia da sua morte (2Rs 15:1-5)", text: "Subiu ao trono com dezesseis anos e reinou \"cinqüenta e dois anos\" em Jerusalém, filho de Jecolias (2Rs 15:2). \"E fez o que era reto aos olhos do Senhor\" (2Rs 15:3), mas os altos não caíram — e a mão de Deus caiu sobre ele: \"o Senhor feriu o rei, e ficou leproso até ao dia da sua morte; e habitou numa casa separada\" (2Rs 15:5). Crônicas explica o golpe: já fortificado, \"exaltou-se o seu coração até se corromper\", e entrou no templo para queimar incenso, ofício que não era seu (2Cr 26:16-19). O reinado mais próspero de Judá terminou numa casa apartada; e foi no ano em que Uzias morreu que Isaías viu quem realmente reinava: \"eu vi também ao Senhor assentado sobre um alto e sublime trono\" (Is 6:1)." },
  "ben-hadade-filho-de-hazael": { title: "Ben-Hadade, filho de Hazael", subtitle: "Rei da Síria depois de Hazael (2Rs 13:3,24)", text: "Herdou de Hazael o trono de Damasco e a mão pesada sobre Israel: o SENHOR entregou o seu povo \"na mão de Hazael, rei da Síria, e na mão de Ben-Hadade, filho de Hazael, todos aqueles dias\" (2Rs 13:3). Mas a opressão tinha prazo, porque a aliança é mais antiga que o império: \"o Senhor teve misericórdia deles\" e \"tornou-se para eles por amor da sua aliança com Abraão, Isaque e Jacó\" (2Rs 13:23). Morto o pai, \"Ben-Hadade, seu filho, reinou em seu lugar\" (2Rs 13:24) — e a palavra das flechas de Eliseu se cumpriu na medida exata: \"três vezes Jeoás o feriu, e recuperou as cidades de Israel\" (2Rs 13:25)." },
  "bidcar": { title: "Bidcar", subtitle: "O capitão de Jeú no campo de Nabote (2Rs 9:25)", text: "Estava ao lado de Jeú quando a flecha atravessou Jorão, e recebeu a ordem que fecha uma conta antiga: \"Toma-o, lança-o no pedaço do campo de Nabote, o jizreelita\" (2Rs 9:25). Jeú lhe lembra que os dois cavalgavam juntos atrás de Acabe no dia da sentença: \"lembra-te de que, indo eu e tu juntos a cavalo após seu pai, Acabe, o Senhor pôs sobre ele esta sentença\" (2Rs 9:25). Bidcar é a testemunha ocular — o mesmo campo, a mesma palavra, cumprida anos depois: \"Por certo vi ontem, à tarde, o sangue de Nabote e o sangue de seus filhos, diz o Senhor\" (2Rs 9:26). Deus não esquece a vinha roubada de um homem pobre." },
  "eliaquim-mordomo": { title: "Eliaquim, filho de Hilquias", subtitle: "O mordomo da casa de Ezequias (2Rs 18:18)", text: "Chefe da casa real, saiu com Sebna e Joá para ouvir o insulto de Rabsaqué junto ao aqueduto (2Rs 18:18). Foi ele quem pediu: \"Rogamos-te que fales aos teus servos em siríaco\", e \"não nos fales em judaico, aos ouvidos do povo\" (2Rs 18:26) — para poupar a fé de quem estava em cima do muro. Voltou ao rei \"com as vestes rasgadas\" (2Rs 18:37) e foi enviado, coberto de saco, ao profeta Isaías (2Rs 19:2). Deste mesmo homem o SENHOR dissera por Isaías: \"chamarei a meu servo Eliaquim, filho de Hilquias\", e \"porei a chave da casa de Davi sobre o seu ombro\" (Is 22:20,22)." },
  "esar-hadom": { title: "Esar-Hadom", subtitle: "Filho de Senaqueribe, rei da Assíria depois dele (2Rs 19:37)", text: "Sobe ao trono sobre o cadáver do pai: mortos Senaqueribe pelas mãos de Adrameleque e Sarezer, \"Esar-Hadom, seu filho, reinou em seu lugar\" (2Rs 19:37). O império que perguntara \"Quais são eles, dentre todos os deuses das terras, que livraram a sua terra da minha mão\" (2Rs 18:35) não conseguiu guardar o próprio rei dentro do templo do próprio deus. Jerusalém, que não tinha exército para opor, ficou de pé porque o SENHOR dissera: \"Não entrará nesta cidade, nem lançará nela flecha alguma\" (2Rs 19:32). Esar-Hadom é o nome da página seguinte: a Assíria continua — mas a palavra do SENHOR já se cumprira." },
  "evil-merodaque": { title: "Evil-Merodaque", subtitle: "Rei da Babilônia que soltou Joaquim da prisão (2Rs 25:27)", text: "O último parágrafo de Reis não é uma vitória, é uma bondade inesperada: no ano trinta e sete do cativeiro, \"Evil-Merodaque, rei de babilônia, no ano em que reinou, levantou a cabeça de Joaquim, rei de Judá, tirando-o da casa da prisão\" (2Rs 25:27). \"E lhe falou benignamente; e pôs o seu trono acima do trono dos reis que estavam com ele\" (2Rs 25:28); trocou-lhe \"as roupas de prisão\", e o rei de Judá \"de contínuo comeu pão na sua presença todos os dias da sua vida\" (2Rs 25:29). O livro que termina em ruínas termina com um filho de Davi vivo, vestido e à mesa — a lâmpada da promessa ainda acesa, em terra estrangeira." },
  "ezequias": { title: "Ezequias", subtitle: "Rei de Judá, filho de Acaz (2Rs 18:1)", text: "\"No Senhor Deus de Israel confiou, de maneira que depois dele não houve quem lhe fosse semelhante entre todos os reis de Judá\" (2Rs 18:5). Tirou os altos, quebrou as estátuas e \"fez em pedaços a serpente de metal que Moisés fizera\" (2Rs 18:4) — até o milagre virara ídolo. Cercado por Senaqueribe, levou a carta blasfema à casa do SENHOR, estendeu-a diante dele e orou: \"tu mesmo, só tu és Deus de todos os reinos da terra\" (2Rs 19:15). Doente de morte, virou o rosto para a parede e chorou, e ouviu: \"Ouvi a tua oração, e vi as tuas lágrimas; eis que eu te sararei\" (2Rs 20:5). Depois mostrou todos os seus tesouros aos enviados da Babilônia e ouviu que tudo aquilo \"será levado a babilônia; não ficará coisa alguma\" (2Rs 20:17) — grande na oração, frágil na prosperidade." },
  "farao-neco": { title: "Faraó Neco", subtitle: "Rei do Egito que matou Josias em Megido (2Rs 23:29)", text: "Subiu \"contra o rei da Assíria, ao rio Eufrates\", e Josias lhe saiu ao encontro: \"e, vendo-o ele, o matou em Megido\" (2Rs 23:29). Depois pesou a mão sobre Judá: prendeu Jeoacaz \"em Ribla, em terra de Hamate, para que não reinasse em Jerusalém\" (2Rs 23:33), impôs tributo à terra e escolheu ele mesmo o rei — \"constituiu rei a Eliaquim, filho de Josias, em lugar de seu pai Josias\" e \"lhe mudou o nome para Jeoiaquim\" (2Rs 23:34). Trocar o nome de um rei é declarar-se dono dele. Crônicas registra o aviso que Josias não quis ouvir: \"não deu ouvidos às palavras de Neco, que saíram da boca de Deus\" (2Cr 35:22)." },
  "geazi": { title: "Geazi", subtitle: "O moço que servia a Eliseu (2Rs 4:12)", text: "Esteve mais perto dos milagres do que qualquer outro e saiu de mãos vazias. Foi ele quem viu a falta da sunamita — \"ela não tem filho, e seu marido é velho\" (2Rs 4:14) — e quem correu com o bordão até o rosto do menino morto, sem resultado: \"O menino não despertou\" (2Rs 4:31). Depois correu atrás de Naamã por prata e roupas, e mentiu ao profeta: \"Teu servo não foi nem a uma nem a outra parte\" (2Rs 5:25). A sentença foi a herança que ele mesmo escolheu: \"a lepra de Naamã se pegará a ti e à tua descendência para sempre\" (2Rs 5:27). Ainda assim, foi a sua boca que, diante do rei, disse: \"esta é a mulher, e este o seu filho a quem Eliseu ressuscitou\" (2Rs 8:5)." },
  "gedalias": { title: "Gedalias", subtitle: "Governador posto por Nabucodonosor sobre o resto de Judá (2Rs 25:22)", text: "Filho de Aicão e neto de Safã, o escrivão de Josias, foi posto \"por governador\" sobre \"o povo que ficara na terra de Judá\" (2Rs 25:22). Aos capitães que vieram a Mizpá jurou e disse: \"Não temais ser servos dos caldeus; ficai na terra, servi ao rei de babilônia, e bem vos irá\" (2Rs 25:24) — o mesmo caminho humilde que Jeremias pregava debaixo do juízo. Durou pouco: no sétimo mês veio Ismael com dez homens, e \"feriram a Gedalias, e ele morreu\" (2Rs 25:25). Com a sua morte, \"todo o povo se levantou, desde o menor até ao maior\" e \"foram ao Egito, porque temiam os caldeus\" (2Rs 25:26): a terra ficou vazia, e o exílio, completo." },
  "hamutal-filha-de-jeremias": { title: "Hamutal, filha de Jeremias", subtitle: "De Libna, mãe de dois reis: Jeoacaz e Zedequias (2Rs 23:31; 24:18)", text: "Duas vezes a Escritura repete o mesmo nome ao apresentar um rei: \"era o nome de sua mãe Hamutal, filha de Jeremias, de Libna\" (2Rs 23:31; 24:18). Mulher de Josias, o rei que \"andou em todo o caminho de Davi, seu pai\" (2Rs 22:2), viu dois filhos seus assentarem-se no trono e nenhum deles seguir o pai. Jeoacaz reinou três meses e morreu no Egito; Zedequias reinou onze anos e viu matarem os filhos diante dos seus olhos antes de lhe vazarem os olhos (2Rs 25:7). Nenhuma casa é boa o bastante para garantir a fé dos filhos: o coração herda-se menos do que o sangue." },
  "hazael": { title: "Hazael", subtitle: "Servo de Ben-Hadade, feito rei da Síria (2Rs 8:13-15)", text: "Eliseu chorou olhando para ele, e disse por quê: \"porás fogo às suas fortalezas, e os seus jovens matarás à espada, e os seus meninos despedaçarás\" (2Rs 8:12). Hazael protestou — \"que é teu servo, que não é mais do que um cão, para fazer tão grande coisa?\" (2Rs 8:13) — e no dia seguinte sufocou o seu senhor com um cobertor molhado e \"reinou em seu lugar\" (2Rs 8:15). Cumpriu-se o que fora dito a Elias em Horebe: \"unge a Hazael rei sobre a Síria\" (1Rs 19:15). Foi vara na mão de Deus contra Israel — \"Hazael os feriu em todas as fronteiras de Israel\" (2Rs 10:32) — e nem por isso deixou de ser culpado de tudo o que fez." },
  "hefziba": { title: "Hefzibá", subtitle: "Mulher de Ezequias, mãe do rei Manassés (2Rs 21:1)", text: "Aparece numa linha só: \"era o nome de sua mãe Hefzibá\" (2Rs 21:1). O nome é uma bênção — é assim que Isaías anuncia o novo nome da cidade restaurada: \"chamar-te-ão: O meu prazer está nela\" (Is 62:4). Mas o filho que ela deu ao maior reformador de Judá tornou-se o pior dos seus reis: \"tornou a edificar os altos que Ezequias, seu pai, tinha destruído\" (2Rs 21:3) e \"derramou muitíssimo sangue inocente\" (2Rs 21:16). Nome de deleite, casa de dor: a piedade dos pais não se transmite por herança, e cada geração tem de crer por si mesma." },
  "hilquias": { title: "Hilquias", subtitle: "O sumo sacerdote que achou o livro da lei (2Rs 22:8)", text: "Enquanto se contava o dinheiro da obra do templo, ele disse a frase que mudou o reinado de Josias: \"Achei o livro da lei na casa do Senhor\" (2Rs 22:8). Entregou-o a Safã, que o leu diante do rei, e o rei rasgou as vestes (2Rs 22:10-11). Foi com os enviados \"à profetisa Hulda\" (2Rs 22:14) e depois executou a limpeza: tirou do templo \"todos os vasos que se tinham feito para Baal, para o bosque e para todo o exército dos céus\" (2Rs 23:4). É terrível que o livro da aliança estivesse perdido dentro da própria casa de Deus — e é a glória daquele reinado que a reforma tenha começado no dia em que alguém o leu em voz alta." },
  "hulda": { title: "Hulda", subtitle: "A profetisa, mulher de Salum, que habitava em Jerusalém na segunda parte (2Rs 22:14)", text: "Achado o livro, o rei mandou os seus cinco homens não a um sacerdote nem a um príncipe, mas \"à profetisa Hulda, mulher de Salum, filho de Ticvá\" (2Rs 22:14). A resposta dela não amaciou nada: \"Assim diz o Senhor Deus de Israel\" (2Rs 22:15), e logo \"Eis que trarei mal sobre este lugar, e sobre os seus moradores\" (2Rs 22:16). Mas trouxe também misericórdia medida ao coração do rei: \"Porquanto o teu coração se enterneceu, e te humilhaste perante o Senhor\", diz o SENHOR, \"também eu te ouvi\" (2Rs 22:19). Uma mulher, na segunda parte da cidade, falando a palavra do SENHOR ao trono de Davi." },
  "isaias": { title: "Isaías, filho de Amós", subtitle: "O profeta nos dias de Ezequias (2Rs 19:2)", text: "Chega a Reis no momento exato em que Jerusalém não tem saída: \"Não temas as palavras que ouviste, com as quais os servos do rei da Assíria me blasfemaram\" (2Rs 19:6). Sobre Senaqueribe pronunciou o oráculo mais implacável da narrativa: \"porei o meu anzol no teu nariz e o meu freio nos teus lábios, e te farei voltar pelo caminho por onde vieste\" (2Rs 19:28). Ao rei doente disse primeiro \"Põe em ordem a tua casa, porque morrerás, e não viverás\" (2Rs 20:1) e, sem ter saído do pátio, teve de voltar com quinze anos de vida. Diante dos tesouros mostrados aos babilônios, anunciou o exílio (2Rs 20:17). A sua visão começara no ano em que morreu Uzias: \"eu vi também ao Senhor assentado sobre um alto e sublime trono\" (Is 6:1)." },
  "ismael-filho-de-netanias": { title: "Ismael, filho de Netanias", subtitle: "Da descendência real, assassino de Gedalias (2Rs 25:25)", text: "Veio a Mizpá com os outros capitães e comeu do pão do governador; depois voltou, no sétimo mês, com dez homens, e matou quem o rei da Babilônia pusera sobre a terra: \"feriram a Gedalias, e ele morreu, como também aos judeus, e aos caldeus que estavam com ele em Mizpá\" (2Rs 25:25). Jeremias diz quem era: \"filho de Netanias, filho de Elisama, de sangue real\" (Jr 41:1) — um príncipe da casa de Davi destruindo o único governo que restava a Judá. O resultado foi a fuga em massa ao Egito, \"porque temiam os caldeus\" (2Rs 25:26). O orgulho ferido de uma casa real acabou de esvaziar a terra que o inimigo já havia arrasado." },
  "jazanias-filho-do-maacatita": { title: "Jazanias, filho do maacatita", subtitle: "Um dos capitães que vieram a Gedalias em Mizpá (2Rs 25:23)", text: "Depois que a cidade caiu e o templo ardeu, os capitães dos exércitos que restavam saíram do campo e vieram ao governador: \"Ismael, filho de Netanias, e Joanã, filho de Careá, e Seraías, filho de Tanumete, o netofatita, e Jazanias, filho do maacatita, eles e os seus homens\" (2Rs 25:23). Vieram armados a um homem sem exército e ouviram um juramento: \"Não temais ser servos dos caldeus; ficai na terra\" (2Rs 25:24). Jazanias é um dos que aceitaram esse pouco. Quando Ismael matou Gedalias, esse pouco também acabou, e \"foram ao Egito, porque temiam os caldeus\" (2Rs 25:26)." },
  "jecolias-mae-de-azarias": { title: "Jecolias", subtitle: "De Jerusalém, mãe do rei Azarias (Uzias) (2Rs 15:2)", text: "\"era o nome de sua mãe Jecolias, de Jerusalém\" (2Rs 15:2) — a mãe do rei que subiu ao trono com dezesseis anos e ali ficou cinqüenta e dois. O filho \"fez o que era reto aos olhos do Senhor, conforme tudo o que fizera Amazias, seu pai\" (2Rs 15:3), e mesmo assim terminou os dias \"numa casa separada\" (2Rs 15:5), leproso. As rainhas-mães de Judá são citadas uma a uma nesses capítulos porque tinham lugar de peso na corte; e a Escritura, ao registrar o nome delas, lembra que atrás de cada reinado houve uma casa e uma mulher." },
  "jedida-filha-de-adaias": { title: "Jedida, filha de Adaías", subtitle: "De Bozcate, mãe do rei Josias (2Rs 22:1)", text: "Mãe de um menino que subiu ao trono com oito anos, depois que assassinaram o avô e o pai: \"era o nome de sua mãe, Jedida, filha de Adaías, de Bozcate\" (2Rs 22:1). Naquela casa não havia exemplo bom — Manassés e Amom. E, contra toda a herança, do menino se escreveu: \"E fez o que era reto aos olhos do Senhor; e andou em todo o caminho de Davi, seu pai, e não se apartou dele nem para a direita nem para a esquerda\" (2Rs 22:2). Não sabemos o que Jedida ensinou; sabemos que a graça de Deus alcançou aquele menino cedo, e que a Escritura guardou o nome da mãe." },
  "jeoacaz": { title: "Jeoacaz", subtitle: "Rei de Judá, filho de Josias, deposto por Faraó Neco (2Rs 23:30-34)", text: "Ungido pelo povo da terra sobre o corpo do pai morto em Megido (2Rs 23:30), reinou \"três meses\" em Jerusalém, filho de Hamutal (2Rs 23:31). Nem a morte de Josias o corrigiu: \"E fez o que era mau aos olhos do Senhor, conforme tudo o que fizeram seus pais\" (2Rs 23:32). Faraó Neco o prendeu \"em Ribla, em terra de Hamate, para que não reinasse em Jerusalém\" (2Rs 23:33) e o levou consigo: \"foi ao Egito, e morreu ali\" (2Rs 23:34). Jeremias, que o chama Salum, selou-lhe o destino: \"no lugar para onde o levaram cativo ali morrerá, e nunca mais verá esta terra\" (Jr 22:12)." },
  "jeoacaz-de-israel": { title: "Jeoacaz, filho de Jeú", subtitle: "Rei de Israel em Samaria, dezessete anos (2Rs 13:1)", text: "Seguiu \"os pecados de Jeroboão, filho de Nebate\" (2Rs 13:2), e a Síria o esmagou até lhe restarem só \"cinqüenta cavaleiros, dez carros e dez mil homens de pé\" (2Rs 13:7) — um exército feito \"como o pó, trilhando-os\". Mas houve um lampejo: \"Jeoacaz suplicou diante da face do Senhor; e o Senhor ouviu; porque viu a opressão de Israel\" (2Rs 13:4), e \"o Senhor deu um salvador a Israel\" (2Rs 13:5). Nem por isso o rei mudou a casa: o bosque continuou de pé em Samaria (2Rs 13:6). Deus ouve o clamor até de um rei mau — o que Ele não faz é fingir que o altar torto está direito." },
  "jeoas-de-israel": { title: "Jeoás, filho de Jeoacaz", subtitle: "Rei de Israel, o que chorou sobre Eliseu moribundo (2Rs 13:10,14)", text: "Fez o que era mau aos olhos do SENHOR (2Rs 13:11) e, ainda assim, desceu ao leito do profeta moribundo e chorou sobre o seu rosto as mesmas palavras que Eliseu gritara por Elias: \"Meu pai, meu pai, o carro de Israel, e seus cavaleiros!\" (2Rs 13:14). Recebeu o arco, atirou para o oriente — \"A flecha do livramento do Senhor\" (2Rs 13:17) — e depois feriu a terra três vezes e parou. Eliseu se indignou: \"Cinco ou seis vezes a deverias ter ferido\" (2Rs 13:19). Teve exatamente o que a sua fé pediu: \"três vezes Jeoás o feriu, e recuperou as cidades de Israel\" (2Rs 13:25). Contra Amazias venceu e humilhou Judá, rompendo o muro de Jerusalém (2Rs 14:13)." },
  "jeoiaquim": { title: "Jeoiaquim", subtitle: "Rei de Judá, o Eliaquim a quem Faraó mudou o nome (2Rs 23:34)", text: "Não foi escolhido por Deus nem pelo povo: Faraó Neco \"constituiu rei a Eliaquim, filho de Josias, em lugar de seu pai Josias\" e \"lhe mudou o nome para Jeoiaquim\" (2Rs 23:34). Para pagar o tributo, tributou os seus: \"a cada um segundo a sua avaliação exigiu a prata e o ouro do povo da terra\" (2Rs 23:35). Depois trocou de senhor: \"subiu Nabucodonosor, rei de babilônia, e Jeoiaquim ficou três anos seu servo; depois se virou, e se rebelou contra ele\" (2Rs 24:1), e vieram sobre Judá as tropas dos caldeus. Jeremias lhe prometeu sepultura de animal: \"Em sepultura de jumento será sepultado, sendo arrastado e lançado para bem longe, fora das portas de Jerusalém\" (Jr 22:19). Foi nos seus dias que começou o cativeiro (Dn 1:1-2)." },
  "jeorao": { title: "Jeorão", subtitle: "Rei de Judá, filho de Jeosafá, casado com a filha de Acabe (2Rs 8:16-18)", text: "\"E andou no caminho dos reis de Israel, como também fizeram os da casa de Acabe, porque tinha por mulher a filha de Acabe\" (2Rs 8:18) — foi por esse casamento que a idolatria do Norte entrou na casa de Davi. Nos seus dias Judá perdeu Edom e Libna (2Rs 8:20,22). E, no meio do relato do seu mal, a narrativa para para dizer por que o reino não caiu: \"Porém o Senhor não quis destruir a Judá por amor de Davi, seu servo, como lhe tinha falado que lhe daria, para sempre, uma lâmpada, a ele e a seus filhos\" (2Rs 8:19). Não é a fidelidade dos reis que sustenta a promessa; é a promessa que sustenta os reis." },
  "jeoseba": { title: "Jeoseba", subtitle: "Filha do rei Jorão, irmã de Acazias, que escondeu o menino Joás (2Rs 11:2)", text: "No dia em que Atalia \"levantou-se, e destruiu toda a descendência real\" (2Rs 11:1), uma mulher da própria casa real desfez o plano: \"Jeoseba, filha do rei Jorão, irmã de Acazias, tomou a Joás, filho de Acazias, furtando-o dentre os filhos do rei, aos quais matavam\" (2Rs 11:2). Escondeu o bebê e a sua ama numa recâmara, e depois o menino \"esteve com ela escondido na casa do Senhor seis anos\" (2Rs 11:3). Toda a linhagem messiânica passou, naquele instante, pelos braços de uma tia corajosa: Deus guardou a lâmpada de Davi (2Rs 8:19) num quarto do templo, enquanto a usurpadora reinava lá fora." },
  "jeroboao-segundo": { title: "Jeroboão, filho de Jeoás", subtitle: "Rei de Israel por quarenta e um anos em Samaria (2Rs 14:23)", text: "Reinou mais tempo que qualquer rei do Norte e \"fez o que era mau aos olhos do Senhor\" (2Rs 14:24) — e, apesar disso, foi por ele que Deus salvou Israel: \"Também este restituiu os termos de Israel, desde a entrada de Hamate, até ao mar da planície\" (2Rs 14:25), conforme a palavra dita pelo profeta Jonas. A razão não estava no rei: \"viu o Senhor que a miséria de Israel era muito amarga, e que nem havia escravo, nem absolvido, nem quem ajudasse a Israel\" (2Rs 14:26). Nos seus dias profetizaram Amós e Oséias (Am 1:1; Os 1:1), e o sacerdote de Betel mandou dizer-lhe: \"Amós tem conspirado contra ti, no meio da casa de Israel\" (Am 7:10). Prosperidade sem arrependimento é a véspera do exílio." },
  "jerusa-filha-de-zadoque": { title: "Jerusa, filha de Zadoque", subtitle: "Mãe do rei Jotão de Judá (2Rs 15:33)", text: "\"era o nome de sua mãe Jerusa, filha de Zadoque\" (2Rs 15:33). O filho governou primeiro em lugar do pai leproso — \"Jotão, filho do rei, tinha o cargo da casa, julgando o povo da terra\" (2Rs 15:5) — e depois em nome próprio, dezesseis anos. Dele a Escritura diz o que raramente diz sem ressalva grave: \"E fez o que era reto aos olhos do Senhor\" (2Rs 15:34). Foi também construtor no templo: \"Este edificou a porta alta da casa do Senhor\" (2Rs 15:35). O nome de Jerusa aparece uma vez só, ligado a um dos poucos reis de quem não se registra maldade alguma." },
  "jeu-rei": { title: "Jeú, filho de Josafá, filho de Ninsi", subtitle: "Ungido rei de Israel para ferir a casa de Acabe (2Rs 9:6)", text: "Um moço profeta derramou-lhe o azeite na cabeça e disse: \"Ungi-te rei sobre o povo do Senhor, sobre Israel\" e \"ferirás a casa de Acabe, teu senhor\" (2Rs 9:6-7). Ele subiu ao carro e não parou: matou Jorão no campo de Nabote, feriu Acazias, mandou lançar Jezabel da janela, decapitou setenta filhos de Acabe e reuniu com astúcia todos os servos de Baal para destruí-los — \"E assim Jeú destruiu a Baal de Israel\" (2Rs 10:28). Deus lhe reconheceu a obra e prometeu-lhe o trono até a quarta geração (2Rs 10:30). Mas o veredito final é duro: \"Jeú não teve cuidado de andar com todo o seu coração na lei do Senhor Deus de Israel\" (2Rs 10:31) — os bezerros de Betel e de Dã ficaram de pé. Zelo furioso contra o pecado alheio ainda não é santidade." },
  "joa-cronista": { title: "Joá, filho de Asafe", subtitle: "O cronista da corte de Ezequias (2Rs 18:18)", text: "Um dos três que saíram ao encontro do exército assírio: \"Eliaquim, filho de Hilquias, o mordomo, e Sebna, o escrivão, e Joá, filho de Asafe, o cronista\" (2Rs 18:18). O cronista guardava a memória oficial do reino; naquele dia teve de ouvir um estrangeiro gritar ao povo em judaico \"Não vos engane Ezequias\" (2Rs 18:29) e blasfemar do Deus vivo. Ele e os companheiros pediram que Rabsaqué falasse \"em siríaco\" (2Rs 18:26), e voltaram \"com as vestes rasgadas\" (2Rs 18:37) — não com um relatório, mas com luto. Há dias em que o dever do escriba é rasgar a veste e correr ao profeta." },
  "joada-mae-de-amazias": { title: "Joadã", subtitle: "De Jerusalém, mãe do rei Amazias de Judá (2Rs 14:2)", text: "\"era o nome de sua mãe Joadã, de Jerusalém\" (2Rs 14:2). Mulher de Joás, o rei que fora escondido no templo, e mãe de Amazias, o rei que vingou o pai sem ultrapassar a lei: \"os filhos dos assassinos não matou, como está escrito no livro da lei de Moisés\" (2Rs 14:6). Do filho a Escritura diz que \"fez o que era reto aos olhos do Senhor, ainda que não como seu pai Davi\" (2Rs 14:3) — e é essa ressalva que descreve quase toda a casa. Joadã é lembrada por uma cláusula, mas está no fio de onde veio o Cristo." },
  "joana-filho-de-carea": { title: "Joanã, filho de Careá", subtitle: "Capitão que veio a Gedalias em Mizpá (2Rs 25:23)", text: "Um dos capitães dos exércitos que, depois da queda de Jerusalém, saíram do campo e vieram ao governador em Mizpá (2Rs 25:23). Aceitaram o juramento de Gedalias: \"Não temais ser servos dos caldeus; ficai na terra, servi ao rei de babilônia, e bem vos irá\" (2Rs 25:24). Foi o último governo que Judá teve na sua própria terra, e durou até o sétimo mês. Depois do assassinato, com os outros capitães, Joanã fez o que Jeremias tanto proibiria: \"todo o povo se levantou, desde o menor até ao maior, como também os capitães dos exércitos, e foram ao Egito, porque temiam os caldeus\" (2Rs 25:26)." },
  "joaquin": { title: "Joaquim", subtitle: "Rei de Judá, filho de Jeoiaquim, levado cativo à Babilônia (2Rs 24:8)", text: "Tinha dezoito anos e \"reinou três meses em Jerusalém\", filho de Neusta (2Rs 24:8). Saiu ao rei que o cercava e foi tomado: \"saiu Joaquim, rei de Judá, ao rei de babilônia, ele, sua mãe, seus servos, seus príncipes e seus oficiais; e o rei de babilônia o tomou preso\" (2Rs 24:12). Com ele foram os tesouros do templo, dez mil presos, os artífices e os ferreiros, e \"ninguém ficou senão o povo pobre da terra\" (2Rs 24:14). Jeremias o chamou Conias e o declarou \"privado de filhos\" quanto ao trono (Jr 22:30). E, no entanto, é ele quem reaparece no último parágrafo do livro, tirado da prisão e comendo à mesa do rei (2Rs 25:27-30) — a última brasa da lâmpada de Davi." },
  "joas-de-juda": { title: "Joás", subtitle: "Rei de Judá, escondido seis anos e coroado aos sete (2Rs 11:21)", text: "\"Era Joás da idade de sete anos quando o fizeram rei\" (2Rs 11:21), depois de seis anos escondido na casa do SENHOR por Jeoseba. Joiada pôs-lhe a coroa e o testemunho, e o povo bateu palmas: \"Viva o rei!\" (2Rs 11:12). Reinou quarenta anos, filho de Zíbia de Berseba, e \"fez Joás o que era reto aos olhos do Senhor todos os dias em que o sacerdote Joiada o dirigia\" (2Rs 12:2) — a ressalva é a chave de tudo. Organizou o reparo do templo pelo cofre à porta (2Rs 12:9), mas comprou a retirada de Hazael com o ouro das coisas santas (2Rs 12:18). Morreu pelas mãos dos seus servos, \"na casa de Milo\" (2Rs 12:20); Crônicas diz por quê: mandara apedrejar Zacarias, filho de Joiada (2Cr 24:21-22)." },
  "joiada": { title: "Joiada", subtitle: "O sacerdote que escondeu, coroou e dirigiu o rei Joás (2Rs 11:4)", text: "No sétimo ano reuniu os centuriões, os capitães e a guarda na casa do SENHOR \"e fez com eles uma aliança e ajuramentou-os na casa do Senhor; e mostrou-lhes o filho do rei\" (2Rs 11:4). Armou-os com \"as lanças e os escudos que haviam sido do rei Davi\" (2Rs 11:10), coroou o menino e não deixou que o sangue de Atalia manchasse o santuário: \"Não a matem na casa do Senhor\" (2Rs 11:15). Depois refez o que mais importava: \"Joiada fez uma aliança entre o Senhor e o rei e o povo, para que fosse o povo do Senhor\" (2Rs 11:17), e o povo derrubou a casa de Baal. Enquanto ele viveu, o rei andou direito (2Rs 12:2) — e Crônicas conta que, morto Joiada, tudo se desfez (2Cr 24:17-18)." },
  "jonadabe-filho-de-recabe": { title: "Jonadabe, filho de Recabe", subtitle: "O que subiu ao carro de Jeú (2Rs 10:15)", text: "Jeú o encontrou no caminho e o sondou: \"Reto é o teu coração para comigo, como o meu o é para contigo?\" (2Rs 10:15). Subiu ao carro e ouviu o convite: \"Vai comigo, e verás o meu zelo para com o Senhor\" (2Rs 10:16); entrou com ele na casa de Baal e assistiu à sua destruição (2Rs 10:23). O nome dele não morreu: séculos depois os recabitas recusaram vinho diante de Jeremias porque \"Jonadabe, filho de Recabe, nosso pai, nos ordenou\" (Jr 35:6), e Deus os honrou: \"Nunca faltará homem a Jonadabe, filho de Recabe, que esteja na minha presença todos os dias\" (Jr 35:19). Uma obediência de família que durou mais do que a dinastia de Jeú." },
  "jonas-filho-de-amitai": { title: "Jonas, filho de Amitai", subtitle: "Profeta de Gate-Hefer, nos dias de Jeroboão II (2Rs 14:25)", text: "Reis o menciona uma vez, e é uma profecia de misericórdia para um rei mau: Jeroboão restituiu os termos de Israel \"conforme a palavra do Senhor Deus de Israel, a qual falara pelo ministério de seu servo Jonas, filho do profeta Amitai, o qual era de Gate-Hefer\" (2Rs 14:25). É o mesmo homem a quem depois se disse \"Levanta-te, vai à grande cidade de Nínive, e clama contra ela\" (Jn 1:2) e que \"se levantou para fugir da presença do Senhor para Társis\" (Jn 1:3). Anunciou graça a Israel de bom grado e a detestou quando foi oferecida a Nínive: \"sabia que és Deus compassivo e misericordioso\" (Jn 4:2). O Senhor Jesus tomou o seu nome como sinal da própria ressurreição (Mt 12:39-41)." },
  "jorao-de-israel": { title: "Jorão, filho de Acabe", subtitle: "Rei de Israel em Samaria, morto por Jeú (2Rs 3:1; 9:24)", text: "Meio caminho e nenhum caminho: \"fez o que era mau aos olhos do Senhor; porém não como seu pai, nem como sua mãe; porque tirou a estátua de Baal, que seu pai fizera\" (2Rs 3:2) e, no entanto, \"aderiu aos pecados de Jeroboão, filho de Nebate\" (2Rs 3:3). Na campanha contra Moabe foi Jeosafá quem procurou um profeta, e Eliseu lhe disse na cara: \"Vai aos profetas de teu pai e aos profetas de tua mãe\" (2Rs 3:13). Ferido pelos sírios em Ramote, foi curar-se em Jizreel, e ali o alcançou o juízo: perguntou \"Há paz, Jeú?\" e ouviu \"Que paz, enquanto as prostituições da tua mãe Jezabel e as suas feitiçarias são tantas?\" (2Rs 9:22). A flecha \"lhe saiu pelo coração\" (2Rs 9:24), e o corpo caiu no campo de Nabote." },
  "josias": { title: "Josias", subtitle: "Rei de Judá que achou o livro da lei e purgou a terra (2Rs 22:1)", text: "Coroado aos oito anos, \"andou em todo o caminho de Davi, seu pai, e não se apartou dele nem para a direita nem para a esquerda\" (2Rs 22:2). Quando lhe leram o livro achado no templo, \"rasgou as suas vestes\" (2Rs 22:11) — e depois agiu: queimou os vasos de Baal, derrubou as casas dos sodomitas, profanou Tofete \"para que ninguém fizesse passar a seu filho, ou sua filha, pelo fogo a Moloque\" (2Rs 23:10), destruiu o altar de Betel e celebrou uma páscoa como não havia \"desde os dias dos juízes que julgaram a Israel\" (2Rs 23:22). Dele está escrito: \"antes dele não houve rei semelhante, que se convertesse ao Senhor com todo o seu coração, com toda a sua alma e com todas as suas forças\" (2Rs 23:25). E, ainda assim, o furor por causa de Manassés não se demoveu (2Rs 23:26)." },
  "jotao-de-juda": { title: "Jotão", subtitle: "Rei de Judá, filho de Uzias (2Rs 15:32-33)", text: "Governou antes de reinar: enquanto o pai leproso morava numa casa separada, \"Jotão, filho do rei, tinha o cargo da casa, julgando o povo da terra\" (2Rs 15:5). Depois reinou dezesseis anos, filho de Jerusa, e \"fez o que era reto aos olhos do Senhor\" (2Rs 15:34), embora os altos continuassem de pé. Construiu no templo: \"Este edificou a porta alta da casa do Senhor\" (2Rs 15:35). Nos seus dias começou a pressão que arrasaria a região: \"Naqueles dias começou o Senhor a enviar contra Judá a Rezim, rei da Síria, e a Peca, filho de Remalias\" (2Rs 15:37). Isaías profetizava então, \"nos dias de Uzias, Jotão, Acaz, e Ezequias, reis de Judá\" (Is 1:1)." },
  "jozabade-filho-de-somer": { title: "Jozabade, filho de Somer", subtitle: "Um dos servos que mataram o rei Joás (2Rs 12:21)", text: "\"Porque Jozacar, filho de Simeate, e Jozabade, filho de Somer, seus servos, o feriram, e morreu\" (2Rs 12:21). O rei que fora salvo em bebê por uma tia e criado por um sacerdote acabou ferido pelos homens da própria casa, \"na casa de Milo, no caminho que desce para Sila\" (2Rs 12:20). Crônicas dá o motivo: \"seus servos conspiraram contra ele por causa do sangue do filho do sacerdote Joiada\" (2Cr 24:25). Sobre esses assassinos ainda pesou a lei: Amazias os matou, mas poupou-lhes os filhos, \"como está escrito no livro da lei de Moisés\" (2Rs 14:6)." },
  "jozacar-filho-de-simeate": { title: "Jozacar, filho de Simeate", subtitle: "Um dos servos que mataram o rei Joás (2Rs 12:21)", text: "A Escritura o nomeia junto com o companheiro do golpe: \"Jozacar, filho de Simeate, e Jozabade, filho de Somer, seus servos, o feriram, e morreu, e o sepultaram com seus pais na cidade de Davi\" (2Rs 12:21). Foi o fim de um reinado que começara com palmas e trombetas e o grito \"Viva o rei!\" (2Rs 11:12). O sangue de Zacarias, filho de Joiada, apedrejado no pátio do templo por ordem do próprio Joás, cobrou-se assim; morrendo, aquele profeta dissera: \"O Senhor o verá, e o requererá\" (2Cr 24:22). O trono que se ergueu sobre a fidelidade de um sacerdote caiu sobre a morte do filho dele." },
  "mata-sacerdote-de-baal": { title: "Matã", subtitle: "Sacerdote de Baal em Jerusalém, morto no dia da coroação de Joás (2Rs 11:18)", text: "Havia em Jerusalém, no reinado de Atalia, uma casa de Baal com altares, imagens e um sacerdote de nome próprio. No dia em que o menino Joás foi coroado, \"todo o povo da terra entrou na casa de Baal, e a derrubaram, como também os seus altares, e as suas imagens, totalmente quebraram, e a Matã, sacerdote de Baal, mataram diante dos altares\" (2Rs 11:18). A reforma não foi apenas política: a aliança que Joiada fez \"entre o Senhor e o rei e o povo\" (2Rs 11:17) exigia que o outro altar caísse. Onde há dois deuses num só reino, um deles é o rei de verdade." },
  "menaem-filho-de-gadi": { title: "Menaém, filho de Gadi", subtitle: "Rei de Israel, dez anos em Samaria (2Rs 15:17)", text: "Subiu de Tirza, matou o usurpador Salum e tomou o trono (2Rs 15:14). O primeiro ato registrado do seu reinado é uma atrocidade: \"Menaém feriu a Tifsa, e a todos os que nela havia\", e \"a todas as mulheres grávidas fendeu pelo meio\" (2Rs 15:16) — exatamente o que Eliseu chorara ao ver em Hazael (2Rs 8:12). Para firmar-se, comprou a Assíria: deu a Pul \"mil talentos de prata, para que este o ajudasse a firmar o reino na sua mão\" (2Rs 15:19), e cobrou a conta dos ricos, \"de cada homem cinqüenta siclos de prata\" (2Rs 15:20). Trono sustentado por dinheiro estrangeiro e sangue de inocentes já está a caminho do exílio." },
  "menina-cativa-de-israel": { title: "A menina cativa de Israel", subtitle: "A serva da mulher de Naamã, que apontou o profeta de Samaria (2Rs 5:2-3)", text: "\"saíram tropas da Síria, da terra de Israel, e levaram presa uma menina que ficou ao serviço da mulher de Naamã\" (2Rs 5:2). Arrancada de casa e escravizada, não guardou rancor: \"Antes o meu senhor estivesse diante do profeta que está em Samaria; ele o restauraria da sua lepra\" (2Rs 5:3). Essa única frase de uma criança sem nome pôs em movimento cartas de reis, dez talentos de prata e uma comitiva inteira — até que o capitão sírio mergulhou sete vezes no Jordão e confessou: \"agora sei que em toda a terra não há Deus senão em Israel\" (2Rs 5:15). Deus usou a testemunha mais fraca da casa para converter o homem mais forte da Síria." },
  "mesa-rei-de-moabe": { title: "Mesa, rei dos moabitas", subtitle: "O criador de gado que se rebelou contra Israel (2Rs 3:4-5)", text: "\"Mesa, rei dos moabitas, era criador de gado, e pagava de tributo, ao rei de Israel, cem mil cordeiros, e cem mil carneiros com a sua lã\" (2Rs 3:4). Morto Acabe, rebelou-se. Quando os três reis vieram sobre ele e o vale amanheceu cheio de água, os moabitas a viram \"vermelhas como sangue\" (2Rs 3:22) e correram à presa, para serem feridos. Cercado em Quir-Haresete, tentou romper com setecentos homens e não pôde; então fez o indizível: \"tomou a seu filho primogênito, que havia de reinar em seu lugar, e o ofereceu em holocausto sobre o muro\" (2Rs 3:27). O desespero pagão sacrifica o filho; o Deus de Israel deu o seu." },
  "mesulemete-filha-de-harus": { title: "Mesulemete, filha de Harus", subtitle: "De Jotbá, mãe do rei Amom de Judá (2Rs 21:19)", text: "\"era o nome de sua mãe Mesulemete, filha de Harus, de Jotbá\" (2Rs 21:19). Mulher de Manassés e mãe de Amom, viveu no reinado mais longo e mais sangrento de Judá, aquele em que o rei \"derramou muitíssimo sangue inocente, até que encheu a Jerusalém de um ao outro extremo\" (2Rs 21:16). O filho não se apartou nada daquilo: \"andou em todo o caminho em que andara seu pai\" (2Rs 21:21) e foi morto dentro de casa em dois anos. E, no entanto, é dessa corte que sai o menino Josias — a graça trabalhando dentro de uma casa arruinada." },
  "naama-siro": { title: "Naamã", subtitle: "Capitão do exército do rei da Síria, leproso e curado no Jordão (2Rs 5:1)", text: "Tudo o que um homem pode ter, e uma palavra que apaga o resto: \"era um grande homem diante do seu SENHOR, e de muito respeito\", mas \"era este homem herói valoroso, porém leproso\" (2Rs 5:1). Indignou-se com a receita simples do profeta — \"Não são porventura Abana e Farpar, rios de Damasco, melhores do que todas as águas de Israel?\" (2Rs 5:12) — e só a insistência dos servos o fez descer. Mergulhou sete vezes \"e a sua carne tornou-se como a carne de um menino\" (2Rs 5:14), e voltou confessando: \"agora sei que em toda a terra não há Deus senão em Israel\" (2Rs 5:15). Pediu terra de Israel para adorar, e ouviu de Eliseu: \"Vai em paz\" (2Rs 5:19). Jesus o apontou aos de Nazaré: \"nenhum deles foi purificado, senão Naamã, o siro\" (Lc 4:27)." },
  "nabucodonosor": { title: "Nabucodonosor", subtitle: "Rei da Babilônia, o que levou Judá cativo (2Rs 24:1)", text: "Entra em Reis como senhor de Jeoiaquim — \"Jeoiaquim ficou três anos seu servo; depois se virou, e se rebelou contra ele\" (2Rs 24:1) — e sai dele como executor do juízo anunciado. Levou Joaquim preso com dez mil de Jerusalém, os artífices e os ferreiros (2Rs 24:14-16); pôs Zedequias no trono e, quando este também se rebelou, veio \"ele e todo o seu exército, e se acampou contra ela, e levantaram contra ela trincheiras em redor\" (2Rs 25:1). Cegou o rei, queimou o templo e derrubou os muros. E, contudo, a Escritura não trata nada disso como acaso: \"assim sucedeu por causa da ira do SENHOR contra Jerusalém\" (2Rs 24:20). O maior império do mundo foi, ali, uma vara na mão de Deus." },
  "nata-meleque-o-camareiro": { title: "Natã-Meleque, o camareiro", subtitle: "O oficial junto de cuja câmara estavam os cavalos do sol (2Rs 23:11)", text: "Nomeado uma vez só, e por causa do lugar onde morava: Josias \"tirou os cavalos que os reis de Judá tinham dedicado ao sol, à entrada da casa do Senhor, perto da câmara de Natã-Meleque, o camareiro\", e \"os carros do sol queimou a fogo\" (2Rs 23:11). O culto ao sol tinha cavalos estacionados à porta do templo do SENHOR, e um funcionário da corte morava ao lado — a idolatria não estava escondida no monte, estava no expediente. Josias não negociou com ela: quebrou, queimou e lançou o pó no Cedrom (2Rs 23:12). Reformar de verdade é mexer no que já virou rotina." },
  "nebuzarada": { title: "Nebuzaradã", subtitle: "Capitão da guarda de Nabucodonosor, que queimou Jerusalém (2Rs 25:8)", text: "Chegou a Jerusalém no quinto mês e \"queimou a casa do Senhor e a casa do rei, como também todas as casas de Jerusalém\" (2Rs 25:9); o exército sob a sua mão \"derrubou os muros em redor de Jerusalém\" (2Rs 25:10). Levou preso o resto do povo e os que se tinham rendido, e — detalhe que a Escritura faz questão de guardar — \"dos mais pobres da terra deixou o capitão da guarda ficar alguns para vinheiros e para lavradores\" (2Rs 25:12). Tomou Seraías, Sofonias e os guardas do umbral e os entregou em Ribla, onde foram mortos (2Rs 25:18-21). A casa que Salomão levara sete anos a erguer ardeu num só dia." },
  "neusta-filha-de-elnata": { title: "Neusta, filha de Elnatã", subtitle: "De Jerusalém, mãe do rei Joaquim (2Rs 24:8)", text: "\"era o nome de sua mãe, Neusta, filha de Elnatã, de Jerusalém\" (2Rs 24:8). Foi levada cativa junto com o filho de dezoito anos: \"saiu Joaquim, rei de Judá, ao rei de babilônia, ele, sua mãe, seus servos, seus príncipes e seus oficiais\" (2Rs 24:12), e a lista dos deportados a repete — \"a mãe do rei, as mulheres do rei, os seus oficiais e os poderosos da terra levou presos\" (2Rs 24:15). A rainha-mãe de Judá tinha assento na corte; naquele dia saiu do palácio para o cativeiro. Jeremias falara desta hora: o anel do selo arrancado da mão direita (Jr 22:24)." },
  "oseias-de-israel": { title: "Oséias, filho de Elá", subtitle: "O último rei de Israel (2Rs 17:1)", text: "\"fez o que era mau aos olhos do Senhor, contudo não como os reis de Israel que foram antes dele\" (2Rs 17:2) — e mesmo assim foi no seu reinado que o Norte acabou. Tornou-se servo de Salmaneser e pagava-lhe tributo, até tentar virar a casaca: \"o rei da Assíria achou em Oséias conspiração; porque enviara mensageiros a Sô, rei do Egito\" (2Rs 17:4). Foi preso na casa do cárcere, Samaria caiu depois de três anos de cerco e \"o rei da Assíria tomou a Samaria, e levou Israel cativo para a Assíria\" (2Rs 17:6). O narrador não culpa a diplomacia, e sim a idolatria de gerações: \"os filhos de Israel pecaram contra o Senhor seu Deus, que os fizera subir da terra do Egito\" (2Rs 17:7)." },
  "peca-filho-de-remalias": { title: "Peca, filho de Remalias", subtitle: "Capitão que matou Pecaías e reinou vinte anos em Israel (2Rs 15:25,27)", text: "Era capitão do próprio rei e o feriu \"no paço da casa do rei, juntamente com Argobe e com Arié\" (2Rs 15:25). Nos seus dias começou o desmembramento de Israel: \"veio Tiglate-Pileser, rei da Assíria\", e levou Gileade, \"a Galiléia, e a toda a terra de Naftali, e os levou à Assíria\" (2Rs 15:29). Com Rezim subiu contra Jerusalém para depor Acaz e não o pôde vencer (2Rs 16:5); foi diante dessa aliança que Isaías advertiu a casa de Davi: \"se não o crerdes, certamente não haveis de permanecer\" (Is 7:9). Acabou como começara: \"Oséias, filho de Elá, conspirou contra Peca, filho de Remalias, e o feriu, e o matou\" (2Rs 15:30)." },
  "pecaias-filho-de-menaem": { title: "Pecaías, filho de Menaém", subtitle: "Rei de Israel por dois anos em Samaria (2Rs 15:23)", text: "Herdou de Menaém um trono comprado com a prata dos ricos de Israel, e não durou dois anos: \"fez o que era mau aos olhos do Senhor; nunca se apartou dos pecados de Jeroboão, filho de Nebate\" (2Rs 15:24). O golpe veio de dentro da própria guarda: \"Peca, filho de Remalias, seu capitão, conspirou contra ele, e o feriu em Samaria, no paço da casa do rei\" (2Rs 15:25), com cinqüenta gileaditas. É a quarta casa real derrubada em poucos anos. Reis narra esses reinados curtos quase em forma de lista — e a monotonia é o argumento: uma nação que não se converte apenas troca o nome de quem se senta no trono." },
  "pul-rei-da-assiria": { title: "Pul, rei da Assíria", subtitle: "O rei a quem Menaém comprou apoio com mil talentos de prata (2Rs 15:19)", text: "\"Então veio Pul, rei da Assíria, contra a terra; e Menaém deu a Pul mil talentos de prata, para que este o ajudasse a firmar o reino na sua mão\" (2Rs 15:19). Foi a primeira vez que a Assíria entrou nas contas de Israel, e entrou como sócia. O preço saiu do bolso do povo: \"de todos os poderosos e ricos\", \"de cada homem cinqüenta siclos de prata\" (2Rs 15:20). O império \"não ficou ali na terra\" (2Rs 15:20), mas não esqueceu o caminho: pouco depois Tiglate-Pileser levaria a Galiléia e Naftali (2Rs 15:29), e Samaria cairia (2Rs 17:6). Quem paga ao lobo para guardar a porta ensina-lhe o caminho de casa." },
  "rabe-saris": { title: "Rabe-Saris", subtitle: "Um dos três oficiais que Senaqueribe enviou a Jerusalém (2Rs 18:17)", text: "O rei da Assíria enviou \"a Tartã, e a Rabe-Saris, e a Rabsaqué, de Laquis, com grande exército ao rei Ezequias, a Jerusalém\" (2Rs 18:17). Rabe-Saris é um título da corte assíria — o chefe dos eunucos —, e a Escritura o registra como nome porque foi assim que o povo do muro o ouviu. Os três pararam \"ao pé do aqueduto da piscina superior, que está junto ao caminho do campo do lavandeiro\" (2Rs 18:17), o mesmo lugar em que Isaías um dia se pusera diante de Acaz (Is 7:3). Vieram com exército e com discurso; falou Rabsaqué, e a resposta veio do céu naquela noite (2Rs 19:35)." },
  "rabsaque": { title: "Rabsaqué", subtitle: "O porta-voz de Senaqueribe diante do muro de Jerusalém (2Rs 18:19)", text: "Falou judaico de propósito, em alta voz, para que o povo do muro entendesse: \"Não vos engane Ezequias; porque não vos poderá livrar da sua mão\" (2Rs 18:29). Zombou do Egito — \"aquele bordão de cana quebrada\" (2Rs 18:21) — e, pior, alistou o SENHOR do seu lado: \"O Senhor me disse: Sobe contra esta terra, e destrói-a\" (2Rs 18:25). Terminou igualando o Deus de Israel aos ídolos das nações: \"Porventura livraram a Samaria da minha mão?\" (2Rs 18:34). O povo \"calou-se\" (2Rs 18:36), e Ezequias levou as palavras ao profeta; a resposta foi que o SENHOR ouvira exatamente aquela afronta (2Rs 19:6). Blasfêmia dita em alta voz continua a ser blasfêmia ouvida no céu." },
  "rezim-rei-da-siria": { title: "Rezim, rei da Síria", subtitle: "Aliado de Peca contra Acaz, morto por Tiglate-Pileser (2Rs 16:9)", text: "\"Naqueles dias começou o Senhor a enviar contra Judá a Rezim, rei da Síria, e a Peca, filho de Remalias\" (2Rs 15:37) — a pressão vem anunciada como coisa que o SENHOR envia. Os dois subiram a Jerusalém e cercaram Acaz, \"porém não o puderam vencer\" (2Rs 16:5); Rezim recuperou Elate e \"lançou fora de Elate os judeus\" (2Rs 16:6). Acaz então comprou a Assíria, e o desfecho foi rápido: \"o rei da Assíria subiu contra Damasco, e tomou-a e levou cativo o povo para Quir, e matou a Rezim\" (2Rs 16:9). Amós já anunciara esse mesmo destino: \"o povo da Síria será levado em cativeiro a Quir, diz o Senhor\" (Am 1:5)." },
  "safa-escriba": { title: "Safã, o escrivão", subtitle: "O escriba de Josias que leu o livro diante do rei (2Rs 22:3,10)", text: "Filho de Azalias, foi enviado ao templo para acertar as contas da obra, e voltou com outra coisa: \"O sacerdote Hilquias me deu um livro. E Safã o leu diante do rei\" (2Rs 22:10). Daquela leitura veio o rasgar das vestes e toda a reforma. Foi também um dos cinco que subiram \"à profetisa Hulda\" (2Rs 22:14). A casa dele atravessou o desastre servindo: o filho Aicão protegeu Jeremias (Jr 26:24), e o neto foi feito governador da terra — \"Gedalias, filho de Aicão, filho de Safã\" (2Rs 25:22). Uma linhagem de homens de escrita e de fé, num tempo em que a Palavra andava perdida." },
  "salmaneser": { title: "Salmaneser", subtitle: "Rei da Assíria que subjugou Oséias e cercou Samaria (2Rs 17:3)", text: "\"Contra ele subiu Salmaneser, rei da Assíria; e Oséias ficou sendo servo dele, e pagava-lhe tributos\" (2Rs 17:3). Descoberta a conspiração com o Egito, veio o cerco: \"o rei da Assíria subiu por toda a terra, e veio até Samaria, e a cercou três anos\" (2Rs 17:5). No sexto ano de Ezequias a cidade caiu (2Rs 18:10) e Israel foi levado para Hala, Habor e as cidades dos medos. A Escritura não explica a queda pela superioridade assíria, mas pela aliança rompida: \"não obedeceram à voz do Senhor seu Deus, antes transgrediram a sua aliança\" (2Rs 18:12)." },
  "salum-filho-de-jabes": { title: "Salum, filho de Jabes", subtitle: "Rei de Israel por um mês (2Rs 15:13)", text: "Matou Zacarias em público — \"conspirou contra ele e feriu-o diante do povo, e matou-o; e reinou em seu lugar\" (2Rs 15:10) — e com esse golpe cumpriu-se a palavra dada a Jeú: \"Teus filhos, até à quarta geração, se assentarão sobre o trono de Israel. E assim foi\" (2Rs 15:12). O reinado dele coube num mês: \"reinou um mês inteiro em Samaria\" (2Rs 15:13), até que Menaém subiu de Tirza e o matou. A Escritura resume tudo em duas linhas e passa adiante. Quem toma o trono pela espada costuma ficar nele só o tempo de a próxima espada chegar." },
  "salum-guarda-das-vestiduras": { title: "Salum, o guarda das vestiduras", subtitle: "Filho de Ticvá, marido da profetisa Hulda (2Rs 22:14)", text: "É apresentado apenas como marido e como funcionário: \"Hulda, mulher de Salum, filho de Ticvá, o filho de Harás, o guarda das vestiduras\" (2Rs 22:14). Cuidava das vestes do templo — um ofício obscuro — e a sua casa ficava em Jerusalém, \"na segunda parte\" (2Rs 22:14). Foi a essa casa que subiram o sumo sacerdote e os oficiais do rei, porque ali estava a palavra do SENHOR. Deus não escolheu o palácio nem o pátio dos sacerdotes para responder a Josias: escolheu a sala de um guarda-roupa do templo." },
  "sarezer": { title: "Sarezer", subtitle: "Filho de Senaqueribe, um dos que o mataram em Nínive (2Rs 19:37)", text: "O nome aparece uma vez só, na sentença final do maior inimigo de Ezequias: \"Adrameleque e Sarezer, seus filhos, o feriram à espada; porém eles escaparam para a terra de Ararate\" (2Rs 19:37). O rei que perguntara \"Quais são eles, dentre todos os deuses das terras, que livraram a sua terra da minha mão\" (2Rs 18:35) morreu adorando o seu, e pelas mãos dos seus. Isaías o dissera antes de acontecer: \"Eis que porei nele um espírito, e ele ouvirá um rumor, e voltará para a sua terra; à espada o farei cair na sua terra\" (2Rs 19:7). Palavra dita, palavra cumprida — inclusive no detalhe da espada." },
  "sebna-escrivao": { title: "Sebna, o escrivão", subtitle: "Oficial da corte de Ezequias (2Rs 18:18)", text: "Saiu com Eliaquim e Joá para ouvir Rabsaqué (2Rs 18:18) e voltou \"com as vestes rasgadas\" (2Rs 18:37); depois foi enviado, coberto de saco, \"ao profeta Isaías, filho de Amós\" (2Rs 19:2). Isaías traz uma nota severa a seu respeito: chamando-o \"Sebna, o mordomo\" (Is 22:15), Deus o repreende por cavar para si \"em lugar alto a sua sepultura\" (Is 22:16) e o sentencia: \"E demitir-te-ei do teu posto, e te arrancarei do teu assento\" (Is 22:19), pondo Eliaquim em seu lugar. Em 2 Reis já o vemos rebaixado de mordomo a escrivão. Deus vê o oficial que constrói o próprio monumento enquanto o povo está em cima do muro." },
  "senaqueribe": { title: "Senaqueribe", subtitle: "Rei da Assíria que subiu contra as cidades fortificadas de Judá (2Rs 18:13)", text: "\"subiu Senaqueribe, rei da Assíria, contra todas as cidades fortificadas de Judá, e as tomou\" (2Rs 18:13); Ezequias pagou trezentos talentos de prata e o ouro das portas do templo, e mesmo assim o exército veio a Jerusalém. Mandou dizer ao rei: \"Não te engane o teu Deus, em quem confias\" (2Rs 19:10). Foi essa carta que Ezequias estendeu diante do SENHOR, e a resposta foi um oráculo de escárnio santo: \"A virgem, a filha de Sião, te despreza, de ti zomba\" (2Rs 19:21). Numa noite o anjo do SENHOR feriu cento e oitenta e cinco mil no arraial (2Rs 19:35); \"Então Senaqueribe, rei da Assíria, partiu, e se foi, e voltou e ficou em Nínive\" (2Rs 19:36), onde os próprios filhos o mataram." },
  "seraias-filho-de-tanumete": { title: "Seraías, filho de Tanumete", subtitle: "O netofatita, capitão que veio a Gedalias em Mizpá (2Rs 25:23)", text: "Um dos capitães dos exércitos que, terminado o cerco, saíram do campo e vieram ao governador: \"Seraías, filho de Tanumete, o netofatita\" (2Rs 25:23). Homens armados sem rei, num país sem templo, procurando um governador nomeado pelo inimigo. Ouviram o juramento de Gedalias — \"ficai na terra, servi ao rei de babilônia, e bem vos irá\" (2Rs 25:24) — e por um instante houve algo parecido com paz. Ismael acabou com isso no sétimo mês, e o resto do povo desceu ao Egito (2Rs 25:25-26). Não se confunda com o primeiro sacerdote do mesmo nome, morto em Ribla (2Rs 25:18)." },
  "seraias-primeiro-sacerdote": { title: "Seraías, o primeiro sacerdote", subtitle: "Sumo sacerdote levado a Ribla e ali morto (2Rs 25:18,21)", text: "\"o capitão-da-guarda tomou a Seraías, primeiro sacerdote, e a Sofonias, segundo sacerdote, e aos três guardas do umbral da porta\" (2Rs 25:18). Levados a Ribla, \"o rei de babilônia os feriu e os matou em Ribla, na terra de Hamate\" (2Rs 25:21). Com o templo queimado e o sumo sacerdote executado, o culto de Israel parou. Mas a linha não se rompeu: \"Seraías gerou a Jeozadaque\" (1Cr 6:14), e \"Jeozadaque foi levado cativo quando o Senhor levou presos a Judá e a Jerusalém pela mão de Nabucodonosor\" (1Cr 6:15) — do filho cativo desse sacerdote morto viria a casa que reergueria o altar depois do exílio." },
  "sofonias-segundo-sacerdote": { title: "Sofonias, o segundo sacerdote", subtitle: "Levado com Seraías a Ribla e ali morto (2Rs 25:18,21)", text: "Segundo na hierarquia do templo, foi preso com o sumo sacerdote e com \"os três guardas do umbral da porta\" (2Rs 25:18) quando Nebuzaradã esvaziou a cidade. Não se lhe registra crime nenhum; morreu porque servia à casa que ardera: \"o rei de babilônia os feriu e os matou em Ribla, na terra de Hamate; e Judá foi levado preso para fora da sua terra\" (2Rs 25:21). O mal que Hulda anunciara a Josias — \"Eis que trarei mal sobre este lugar, e sobre os seus moradores\" (2Rs 22:16) — chegou até os degraus do santuário. Não há ofício sagrado que isente do juízo quando a casa toda o mereceu." },
  "sunamita": { title: "A sunamita", subtitle: "A mulher importante de Suném que hospedou Eliseu (2Rs 4:8)", text: "\"havia ali uma mulher importante, a qual o reteve para comer pão\" (2Rs 4:8), e ela disse ao marido: \"Eis que tenho observado que este que sempre passa por nós é um santo homem de Deus\" (2Rs 4:9) — e lhe fez um quarto com cama, mesa, cadeira e candeeiro. Não pediu nada em troca: \"Eu habito no meio do meu povo\" (2Rs 4:13). Recebeu um filho pela palavra do profeta e, quando o menino morreu nos seus joelhos, deitou-o na cama do homem de Deus, correu ao Carmelo e respondeu ao mensageiro apenas: \"Vai bem\" (2Rs 4:26). Não largou o profeta — \"não te hei de deixar\" (2Rs 4:30) — até que o menino espirrou sete vezes. Hebreus registra essa fé: \"As mulheres receberam pela ressurreição os seus mortos\" (Hb 11:35)." },
  "tarta": { title: "Tartã", subtitle: "O comandante do exército enviado por Senaqueribe (2Rs 18:17)", text: "Vem em primeiro lugar na lista dos três: \"a Tartã, e a Rabe-Saris, e a Rabsaqué, de Laquis, com grande exército ao rei Ezequias, a Jerusalém\" (2Rs 18:17). Tartã era o título do general-em-chefe da Assíria: é a força bruta parada diante do muro enquanto o outro fala. Os três se puseram \"ao pé do aqueduto da piscina superior, que está junto ao caminho do campo do lavandeiro\" (2Rs 18:17) — o mesmo lugar em que Isaías dissera a Acaz que não temesse os dois reis coligados (Is 7:3-4). Contra esse exército Ezequias não pôs soldados: pôs uma carta aberta diante do SENHOR (2Rs 19:14)." },
  "tiglate-pileser": { title: "Tiglate-Pileser", subtitle: "Rei da Assíria, o que levou a Galiléia e Naftali (2Rs 15:29)", text: "Nos dias de Peca \"veio Tiglate-Pileser, rei da Assíria\", e tomou Ijom, Abel-Bete-Maaca, Janoa, Quedes, Hazor, Gileade, \"a Galiléia, e a toda a terra de Naftali, e os levou à Assíria\" (2Rs 15:29) — o primeiro grande arrancar de Israel da sua terra. Acaz o chamou contra Damasco com um presente tirado da casa do SENHOR e a mensagem \"Eu sou teu servo e teu filho\" (2Rs 16:7). O assírio atendeu, matou Rezim e levou o povo para Quir (2Rs 16:9). Depois Acaz foi a Damasco encontrar-se com ele e voltou de lá com o desenho de um altar pagão para o templo de Jerusalém (2Rs 16:10). Chamar o império para ajudar sai caro: paga-se em prata e em fé." },
  "urias-sacerdote": { title: "Urias, o sacerdote", subtitle: "O que edificou em Jerusalém o altar copiado de Damasco (2Rs 16:11)", text: "Recebeu de Acaz, que estava em Damasco, \"o desenho e o modelo do altar, conforme toda a sua feitura\" (2Rs 16:10), e não hesitou: \"Urias, o sacerdote, edificou um altar conforme tudo o que o rei Acaz lhe tinha enviado de Damasco\" (2Rs 16:11) — pronto antes de o rei chegar. Depois obedeceu à ordem de empurrar para o lado o altar de cobre do SENHOR e queimar tudo no altar novo (2Rs 16:14-15), e a Escritura sela o seu retrato numa frase: \"E fez Urias, o sacerdote, conforme tudo quanto o rei Acaz lhe ordenara\" (2Rs 16:16). O sacerdote existe para guardar o culto contra o rei quando é preciso; este guardou o rei contra o culto." },
  "viuva-do-azeite": { title: "A viúva do azeite", subtitle: "Mulher de um dos filhos dos profetas, socorrida por Eliseu (2Rs 4:1)", text: "\"Meu marido, teu servo, morreu; e tu sabes que o teu servo temia ao SENHOR; e veio o credor, para levar os meus dois filhos para serem servos\" (2Rs 4:1) — um homem temente a Deus deixou dívidas, e o credor podia tomar-lhe os filhos. Em casa tinha apenas \"uma botija de azeite\" (2Rs 4:2), e foi essa a medida por onde o milagre começou. Eliseu mandou pedir vasilhas emprestadas \"não poucas\" (2Rs 4:3), fechar a porta e derramar; quando o filho disse \"Não há mais vasilha alguma\", então \"o azeite parou\" (2Rs 4:6). Deus encheu tudo o que ela teve fé para trazer. E o fim é sóbrio e santo: \"Vai, vende o azeite, e paga a tua dívida; e tu e teus filhos vivei do resto\" (2Rs 4:7)." },
  "zacarias-filho-de-jeroboao": { title: "Zacarias, filho de Jeroboão", subtitle: "Rei de Israel por seis meses, o último da casa de Jeú (2Rs 15:8)", text: "Reinou \"seis meses\" (2Rs 15:8) e fez como os pais, sem se apartar dos pecados de Jeroboão, filho de Nebate (2Rs 15:9). Salum \"conspirou contra ele e feriu-o diante do povo, e matou-o\" (2Rs 15:10) — assassinato às claras, sem pudor nenhum. O narrador então explica o sentido do que acabou de contar: \"Esta foi a palavra do Senhor, que falou a Jeú: Teus filhos, até à quarta geração, se assentarão sobre o trono de Israel. E assim foi\" (2Rs 15:12). A promessa feita a Jeú era também um limite, e o limite chegou. Deus cumpre exatamente o que prometeu — inclusive o prazo." },
  "zebida-filha-de-pedaias": { title: "Zebida, filha de Pedaías", subtitle: "De Ruma, mãe do rei Jeoiaquim (2Rs 23:36)", text: "\"era o nome de sua mãe Zebida, filha de Pedaías, de Ruma\" (2Rs 23:36). Mulher de Josias, o rei da grande reforma, e mãe do filho a quem Faraó Neco pôs no trono e trocou o nome. Do filho ficou escrito o veredito de sempre: \"fez o que era mau aos olhos do Senhor, conforme tudo quanto fizeram seus pais\" (2Rs 23:37). Foi nos dias dele que Nabucodonosor subiu e Judá começou a ser levado (2Rs 24:1). Uma geração separa a páscoa de Josias do cerco da Babilônia — e as duas saíram da mesma casa." },
  "zedequias-de-juda": { title: "Zedequias", subtitle: "O Matanias a quem a Babilônia mudou o nome; último rei de Judá (2Rs 24:17)", text: "Não foi coroado por Judá: \"o rei de babilônia estabeleceu a Matanias, seu tio, rei em seu lugar; e lhe mudou o nome para Zedequias\" (2Rs 24:17). Reinou onze anos, filho de Hamutal, \"e fez o que era mau aos olhos do Senhor\" (2Rs 24:19), e por fim \"se rebelou contra o rei de babilônia\" (2Rs 24:20). Veio o cerco de dois anos, a fome — \"nem havia pão para o povo da terra\" (2Rs 25:3) — e a fuga de noite pela porta entre os dois muros. Alcançado nas campinas de Jericó, ouviu a sentença em Ribla: \"aos filhos de Zedequias mataram diante dos seus olhos; e vazaram os olhos de Zedequias\" (2Rs 25:7). A última coisa que viu foi o preço da sua rebeldia." },
  "zibia-de-berseba": { title: "Zíbia, de Berseba", subtitle: "Mãe do rei Joás de Judá (2Rs 12:1)", text: "\"era o nome de sua mãe Zíbia, de Berseba\" (2Rs 12:1). O filho dela foi o bebê furtado por Jeoseba dentre os filhos do rei que Atalia matava, criado seis anos escondido na casa do SENHOR (2Rs 11:2-3) e coroado aos sete. Reinou quarenta anos em Jerusalém e \"fez Joás o que era reto aos olhos do Senhor todos os dias em que o sacerdote Joiada o dirigia\" (2Rs 12:2). Zíbia é lembrada como as outras rainhas-mães de Judá: um nome dentro de uma fórmula. Mas essa fórmula é o modo que a Escritura tem de dizer que nenhum rei nasce do nada." },
};
